@startuml

class Customer {
  + name : string
  + surname : string
  + email : string
  + telephone : string
  + homeAddress : string
}

class Order {
  + totalCost : float
  + estimatedDeliveryTime : time
  + status : string
}

class Dish {
  + name : string
  + preparationTime : time
}

class Payment {
  + method : string
  + isSuccessful : boolean
}

class Delivery {
  + shipmentTime : time
  + completionTime : time
}

Customer "1" -- "*" Order : places
Order "1" *-- "1..*" Dish : contains
Order "1" -- "0..1" Payment : processed by
Order "1" -- "0..1" Delivery : fulfilled by

@enduml

